    configOrderToolBar: ['edit', 'remove', 'gerenciamento', '-', '->', 'download'],

    rendererPendencies: function(value){
        return '<p style="text-align:right">' + value + ' pendencia(s)</p>';
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {header: '', dataIndex: 'icons', width: 50, renderer: toolkit.util.rendererIconGrid},
                    {header: 'Tipo de Folha', dataIndex: 'tipo_folha_unicode', width: 200},
                    {header: 'Período', dataIndex: 'periodo_unicode', id: 'autoExpandColumn'},
                    {header: 'Complemento', dataIndex: 'complement_display', width: 100},
                    {header: 'Pagamento em', dataIndex: 'dt_pagamento', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Fechado', dataIndex: 'fechado_por_unicode', width: 170},
                    {header: 'Processado', dataIndex: 'processado_por_unicode', width: 170},
                    {header: 'Folha', dataIndex: 'pendencia_folha', width: 100, renderer: this.rendererPendencies},
                    {header: 'Cont. Interno', dataIndex: 'pendencia_controle', width: 100, renderer: this.rendererPendencies},
                ]
            );

        return this._columnModel;
    },

    editPeriod: function(){

        var selected = this.getSelectionModel().getSelected();

        if(selected) {
            new rh.gfp.payroll.PeriodWindow({
                action: 'update',
                values: 'remote',
                oId: selected.get('periodo'),
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                },
                status_callback: this.status_callback,
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    editMessage: function() {


        var selected = this.getSelectionModel().getSelected();
        // console.debug(selected);
        if(selected){
            new rh.gfp.payroll.PayrollMessageWindow({
                action: (selected.data.message ? 'update' : 'create'),
                values: 'remote',
                oId: selected.get('message'),
                params: {
                    folha: selected.get('pk')
                },
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                },
                status_callback: this.status_callback,
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    buildDirf: function() {
        new Ext.Window({
            title: 'Gerador da DIRF',
            closable: true,
            resizable: false,
            width: 560,
            modal: true,
            border: false,
            items: new toolkit.gfp.dirf.Gerador()
        }).show();
    },

    buildReportResumoEventosConsignatario: function() {

        var selection = this.getSelectionModel().getSelected();

        if(selection) {
            new toolkit.gfp.ResumoGeralEventoConsignatario({
                params: {
                    folha: selection.get('pk')
                }
            }).show();
        }
        else new toolkit.gfp.ResumoGeralEventoConsignatario().show();
    },

    loadFile: function(){
        var selected = this.getSelectionModel().getSelected();
        if(selected)
            new toolkit.gfp.LoaderFileGFP({payroll: selected.data}).show();
        else
            Ext.Msg.show({
                msg: 'Primeiro selecione a folha para a qual deseja carregar o arquivo de lançamentos!',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
    },

    LoaderFileGFP2: Ext.extend(
        Ext.Window,
        {
            getFormPanel: function(cfg) {
                if(!this.formPanel)
                    this.formPanel = new Ext.form.FormPanel({
                        // frame: true,
                        items: [
                            {
                                xtype: 'rest-autocompletefield',
                                fieldLabel: 'Folha',
                                name: 'payroll',
                                rest: 'rh.gfp.payroll.PayrollRestful',
                                value: (cfg && cfg.payroll? cfg.payroll.pk: ''),
                                allowBlank: false,
                            },{
                                xtype: 'rest-autocompletefield',
                                fieldLabel: 'Carregador',
                                name: 'loader',
                                rest: 'rh.gfp.classcode.LoaderRestful',
                                allowBlank: false,
                            },{
                                fieldLabel: 'Arquivo',
                                xtype: 'ged-fileuploadfield',
                                name: 'file',
                                allowBlank: false,
                                width: 380
                            },{
                                xtype: 'rest-autocompletefield',
                                fieldLabel: 'Evento',
                                name: 'event',
                                rest: 'rh.gfp.payroll.EventRestful',
                            },
                        ],
                    });

                return this.formPanel;
            },
            execute: function(){
                var form = this.getFormPanel().getForm();

                form.waitMsgTarget = this.getFormPanel().getEl();
                form.submit({
                    url: toolkit.util.Normalize.controller_action('GFPPayroll', 'load_file'),
                    failure: function(form, action) {
                        console.debug(action);
                    },
                    scope: this,
                    waitMsg: 'Aguarde ...'
                });
            },

            constructor: function(cfg) {
                if(!cfg) cfg = {}

                Ext.apply(
                    cfg,
                    {
                        title: 'Carregar arquivos do FOPAG',
                        closable: true,
                        resizable: false,
                        width: 500,
                        border: false,
                        modal: true,
                        items: [
                            this.getFormPanel(cfg),
                        ],
                        buttons: [
                            {
                                text: 'Carregar',
                                scope: this,
                                handler: this.execute
                            },
                            {
                                text: 'Cancelar',
                                scope: this,
                                handler: this.destroy
                            }
                        ]
                    }
                );

                rh.gfp.LoaderFileGFP2.superclass.constructor.call(this, cfg);
            }
        }
    ),

